147	// `prefix` filters candidate basenames; empty accepts any executable. The
148	// default verilator/build scan passes "sim_"; a user-curated engines dir passes
149	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
150	// lives in the call site, not in this engine-agnostic scanner.
151	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
152	              std::set<std::string>& seen) {
153	  std::error_code ec;
154	  if (!fs::is_directory(dir, ec)) return;
155	
156	  std::vector<fs::path> entries;
157	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
158	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
159	
160	  for (const fs::path& p : entries) {
161	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
162	    if (!is_executable_file(p)) continue;
163	    EngineDescriptor d;
164	    std::string warn;
165	    if (describe_one(p, d, warn)) {
166	      normalize_engine_label(d);  // verilator -> vsim, before dedup keys on id
167	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
168	    } else if (!warn.empty()) {
169	      out.warnings.push_back(warn);
170	    }
171	  }
172	}
173	
174	}  // namespace
