176	// See engine_registry.hpp. VSIM_BIN_DIR (the external prebuilt vsim build,
177	// mirroring QEMU_BIN_DIR) resolved env-first then from config.env, so the driver
178	// finds the external vsim without a prior `source ./setup.sh`; only an
179	// unset-everywhere value falls back to the legacy in-tree build dir.
180	fs::path vsim_scan_dir() {
181	  if (std::string v = config_env_value("VSIM_BIN_DIR"); !v.empty()) return v;
182	  return repo_root() / "verilator" / "build";
183	}
184	
185	Discovery discover_engines() {
186	  Discovery out;
187	  std::set<std::string> seen;
188	
189	  EngineDescriptor qemu = builtin_qemu();
190	  seen.insert(qemu.id);
191	  out.engines.push_back(std::move(qemu));
192	
193	  // rv32 functional engine, listed alongside qemu so `list engines` shows both
194	  // (its binary is qemu-system-riscv32 under the same QEMU_BIN_DIR).
195	  EngineDescriptor qemu32 = builtin_qemu_arch(32);
196	  seen.insert(qemu32.id);
197	  out.engines.push_back(std::move(qemu32));
198	
199	  if (const char* env = std::getenv("ANDESIM_ENGINES_DIR"); env && *env) {
200	    std::stringstream ss(env);
201	    std::string dir;
202	    while (std::getline(ss, dir, ':'))
203	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
204	  } else {
205	    scan_dir(vsim_scan_dir(), /*prefix=*/"sim_", out, seen);
206	  }
207	  return out;
208	}
209	
210	}  // namespace andes_sim
